using System.Windows;
using System.Windows.Controls;
using System.Windows.Documents;
using System.Windows.Media;
using System.Windows.Shapes;
using Path = System.Windows.Shapes.Path;

namespace SpaceSharp.Controls;

/// <summary>
/// Draws one of the app's icons (Themes/Icons.xaml, generated by tools/make-icons.py) at any size. The geometry
/// is on a 24 x 24 grid and is stroked 2 units wide with round caps and joins, as Lucide draws them; the Viewbox
/// scales the picture and the stroke together, so a 14 px icon has a 1.2 px line and a 32 px one a 2.7 px line.
/// The color is <see cref="Foreground"/>, which inherits like text, so an icon inside a button or a menu item
/// takes that control's foreground unless told otherwise.
/// </summary>
public sealed class Icon : Viewbox
{
    public static readonly DependencyProperty GlyphProperty = DependencyProperty.Register(
        nameof(Glyph), typeof(Geometry), typeof(Icon), new PropertyMetadata(null, (d, e) => ((Icon)d)._path.Data = (Geometry?)e.NewValue));

    public static readonly DependencyProperty ForegroundProperty = TextElement.ForegroundProperty.AddOwner(typeof(Icon));

    public static readonly DependencyProperty StrokeWidthProperty = DependencyProperty.Register(
        nameof(StrokeWidth), typeof(double), typeof(Icon), new PropertyMetadata(2.0, (d, e) => ((Icon)d)._path.StrokeThickness = (double)e.NewValue));

    private readonly Path _path;

    static Icon()
    {
        // 14 px unless a style or the markup says otherwise (a local value in the constructor would beat a style's setter)
        WidthProperty.OverrideMetadata(typeof(Icon), new FrameworkPropertyMetadata(14.0));
        HeightProperty.OverrideMetadata(typeof(Icon), new FrameworkPropertyMetadata(14.0));
    }

    public Icon()
    {
        _path = new Path
        {
            Width = 24, Height = 24, StrokeThickness = 2,
            StrokeStartLineCap = PenLineCap.Round, StrokeEndLineCap = PenLineCap.Round, StrokeLineJoin = PenLineJoin.Round,
            Stretch = Stretch.None
        };
        _path.SetBinding(Shape.StrokeProperty, new System.Windows.Data.Binding(nameof(Foreground)) { Source = this });
        Child = _path;
        IsHitTestVisible = false;
    }

    /// <summary>The path to draw, usually {StaticResource Icon.Name} or <see cref="Icons.Get"/>.</summary>
    public Geometry? Glyph { get => (Geometry?)GetValue(GlyphProperty); set => SetValue(GlyphProperty, value); }

    public Brush Foreground { get => (Brush)GetValue(ForegroundProperty); set => SetValue(ForegroundProperty, value); }

    /// <summary>Stroke width on the 24-unit grid; 2 is Lucide's own, 1.5 reads lighter at large sizes.</summary>
    public double StrokeWidth { get => (double)GetValue(StrokeWidthProperty); set => SetValue(StrokeWidthProperty, value); }
}

/// <summary>Looks up icon geometry by name from code: Icons.Get("Delete") is {StaticResource Icon.Delete}.</summary>
public static class Icons
{
    public static Geometry Get(string name) => (Geometry)Application.Current.FindResource("Icon." + name);

    /// <summary>A ready-made icon element, for code that builds its UI by hand.</summary>
    public static Icon Make(string name, double size = 14, string? foregroundKey = null)
    {
        var icon = new Icon { Glyph = Get(name), Width = size, Height = size, VerticalAlignment = VerticalAlignment.Center };
        if (foregroundKey is not null) icon.SetResourceReference(Icon.ForegroundProperty, foregroundKey);
        return icon;
    }
}
